import { Node3D, Camera3D, Color, Environment, WorldEnvironment, DirectionalLight3D, Vector3, RenderingServer, OS, AnimationPlayer, Node } from "godot";
import { instantiatePresentationScene } from "./presentation";
export default class AssaultBodyCapture extends Node3D {
    godot_cli_action(request: string): string {
        if (!OS.is_debug_build()) return JSON.stringify({ accepted: false });
        const a = JSON.parse(request), output = a.payload?.output;
        if (a.name !== "capture" || typeof output !== "string" || !/^[A-Za-z]:[\\/].*\.png$/.test(output)) return JSON.stringify({ accepted: false });
        RenderingServer.force_draw(false, 0);
        const error = this.get_viewport()!.get_texture()!.get_image()!.save_png(output);
        return JSON.stringify({ accepted: error === 0, error, output });
    }
    _ready(): void {
        const env = new Environment(); env.background_mode = Environment.BGMode.BG_COLOR; env.background_color = new Color(0.75, 0.77, 0.79, 1); env.ambient_light_source = Environment.AmbientSource.AMBIENT_SOURCE_COLOR; env.ambient_light_color = new Color(1, 1, 1, 1); env.ambient_light_energy = 0.8;
        const we = new WorldEnvironment(); we.environment = env; this.add_child(we);
        const light = new DirectionalLight3D(); light.rotation_degrees = new Vector3(-30, -30, 0); light.light_energy = 1.5; this.add_child(light);
        const camera = new Camera3D(); camera.projection = Camera3D.ProjectionType.PROJECTION_ORTHOGONAL; camera.size = 2.45; camera.position = new Vector3(0, 1.05, 8); this.add_child(camera); camera.current = true;
        for (let i = 0; i < 3; i++) {
            const body = instantiatePresentationScene("res://assets/characters/mixamo/character-assault.glb")!;
            this.add_child(body); body.position = new Vector3((i - 1) * 1.4, 0, 0); body.rotation_degrees = new Vector3(0, [0, -40, 180][i], 0);
            const visit = (node: Node): void => { if (node instanceof AnimationPlayer) { node.play("TPose"); node.seek(0, true); node.pause(); } for (const c of node.get_children()) visit(c); }; visit(body);
        }
        this.set_meta("godot_cli_state", JSON.stringify({ source: "character-assault.glb", views: ["front", "three-quarter", "back"], materials: "original", pose: "native TPose", fixture: "production presentation scene in isolated Godot review stage" }));
    }
}
